insert into reviews.reviews (id, product_id, app, user_name, avatar, rating, comment, date_label) values
  ('prv-1', 'fm-m1', 'MART'::app_brand, 'Karan Malhotra', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Flagship speed and an incredible camera. Battery easily lasts a full day.', '1 week ago'),
  ('prv-2', 'fm-m1', 'MART'::app_brand, 'Ishita Roy', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Smooth display and premium build. Worth every rupee.', '2 weeks ago'),
  ('prv-3', 'fm-m1', 'MART'::app_brand, 'Rohan Khanna', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Great phone, though a bit heavy. Charging is super fast.', '3 weeks ago'),
  ('prv-4', 'fm-m1', 'MART'::app_brand, 'Divya Krishnan', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Camera clarity is outstanding, especially in low light.', '1 month ago'),
  ('prv-5', 'fm-e1', 'MART'::app_brand, 'Suresh Iyer', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Noise cancellation is fantastic. Super comfortable for long calls.', '4 days ago'),
  ('prv-6', 'fm-e1', 'MART'::app_brand, 'Pooja Nair', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Great bass and build. Battery could be slightly better.', '1 week ago'),
  ('prv-7', 'fm-e1', 'MART'::app_brand, 'Arnav Deshpande', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Best value in this price range. Crisp, balanced sound.', '2 weeks ago'),
  ('prv-8', 'fm-b1', 'MART'::app_brand, 'Tanvi Joshi', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Skin felt hydrated from day one. Non-greasy and light.', '3 days ago'),
  ('prv-9', 'fm-b1', 'MART'::app_brand, 'Kavya Menon', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Works well, mild fragrance. Pump bottle is convenient.', '1 week ago'),
  ('prv-10', 'fm-b1', 'MART'::app_brand, 'Ishita Roy', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Visible glow in two weeks. Genuine product with good packaging.', '2 weeks ago'),
  ('prv-11', 'fm-f1', 'MART'::app_brand, 'Aditya Rao', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Perfect fit and heavy fabric. Exactly as shown.', '5 days ago'),
  ('prv-12', 'fm-f1', 'MART'::app_brand, 'Rohan Khanna', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Great hoodie, runs a touch small. Order a size up.', '1 week ago'),
  ('prv-13', 'fm-f1', 'MART'::app_brand, 'Suresh Iyer', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Comfortable and warm. Colour matches the listing.', '2 weeks ago'),
  ('prv-14', 'fm-fur1', 'MART'::app_brand, 'Divya Krishnan', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Excellent lumbar support, great for 8-hour workdays.', '1 week ago'),
  ('prv-15', 'fm-fur1', 'MART'::app_brand, 'Arnav Deshpande', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Premium mesh, smooth recline, sturdy base. Love it.', '2 weeks ago'),
  ('prv-16', 'fm-fur1', 'MART'::app_brand, 'Karan Malhotra', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Very comfortable. Assembly took a little effort.', '3 weeks ago'),
  ('prv-17', 'gr-p1', 'MART'::app_brand, 'Pooja Nair', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Crisp and sweet. Delivered fresh and well packed.', '2 days ago'),
  ('prv-18', 'gr-p1', 'MART'::app_brand, 'Tanvi Joshi', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Good quality apples, slight variation in size.', '1 week ago'),
  ('prv-19', 'gr-p1', 'MART'::app_brand, 'Suresh Iyer', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Perfect for a healthy snack. Repeat order coming.', '2 weeks ago'),
  ('prv-20', 'sp-1', 'MART'::app_brand, 'Aarav Sharma', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Rich, aromatic and generously portioned. Best biryani in town.', '2 days ago'),
  ('prv-21', 'sp-1', 'MART'::app_brand, 'Rahul Verma', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Authentic Hyderabadi taste. The raita and salan were a bonus.', '1 week ago'),
  ('prv-22', 'sp-1', 'MART'::app_brand, 'Priya Patel', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Delicious but a little oily. Great value though.', '2 weeks ago'),
  ('prv-23', 'm-italian-margherita', 'FOOD'::app_brand, 'Meera Nair', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Wood-fired perfection with fresh bufala. Crust is superb.', '3 days ago'),
  ('prv-24', 'm-italian-margherita', 'FOOD'::app_brand, 'Vikram Singh', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Authentic Neapolitan-style. Cheese quality is excellent.', '1 week ago'),
  ('prv-25', 'm-italian-margherita', 'FOOD'::app_brand, 'Ananya Gupta', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Great pizza, delivery was a touch slow.', '2 weeks ago'),
  ('prv-26', 'm-korean-fc', 'FOOD'::app_brand, 'Ravi Desai', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Crispy, sticky, saucy perfection. Better than many KFCs.', '4 days ago'),
  ('prv-27', 'm-korean-fc', 'FOOD'::app_brand, 'Neha Kapoor', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Sweet-soy glaze is addictive. Portion is generous.', '1 week ago'),
  ('prv-28', 'm-korean-fc', 'FOOD'::app_brand, 'Meera Nair', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Tasty, though arrived slightly less crispy.', '2 weeks ago'),
  ('prv-29', 'ph-f1', 'PHARMA'::app_brand, 'Dr. Sarah Alvi', 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Genuine batch, clear expiry. Reliable for fever and pain.', '3 days ago'),
  ('prv-30', 'ph-f1', 'PHARMA'::app_brand, 'Rahul Verma', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Fast relief and well packaged. Delivery was prompt.', '1 week ago'),
  ('prv-31', 'ph-f1', 'PHARMA'::app_brand, 'Priya Patel', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Works well. Wish the strip pack had more tablets.', '2 weeks ago'),
  ('prv-32', 'ph-ayur1', 'PHARMA'::app_brand, 'Suresh Iyer', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Traditional taste, authentic amla. Good for daily immunity.', '1 week ago'),
  ('prv-33', 'ph-ayur1', 'PHARMA'::app_brand, 'Ishita Roy', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Quality chyawanprash, slightly sweet for my liking.', '2 weeks ago'),
  ('prv-34', 'ph-ayur1', 'PHARMA'::app_brand, 'Kavya Menon', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Family has used this brand for years. Genuine product.', '1 month ago'),
  ('prv-35', 'ph-t3', 'PHARMA'::app_brand, 'Arnav Deshpande', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Good strength capsules, easy to swallow. Value pack.', '5 days ago'),
  ('prv-36', 'ph-t3', 'PHARMA'::app_brand, 'Pooja Nair', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?fm=jpg&fit=crop&q=80&w=56&h=56', 4, 'Helps with energy. Packaging is fine.', '1 week ago'),
  ('prv-37', 'ph-t3', 'PHARMA'::app_brand, 'Divya Krishnan', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?fm=jpg&fit=crop&q=80&w=56&h=56', 5, 'Great price for the count. Genuine stock.', '2 weeks ago');
