insert into reviews.vendor_reviews (id, vendor_id, app, user_id, user_name, rating, comment, order_ids, date_label) values
  ('vr-g1-1', 'store-g1', 'MART'::app_brand, 'seed-pooja-nair', 'Pooja Nair', 5, 'Fresh produce every single time. The apples and milk are my weekly staples now.', ARRAY[]::text[], '2 days ago'),
  ('vr-g1-2', 'store-g1', 'MART'::app_brand, 'seed-suresh-iyer', 'Suresh Iyer', 4, 'Great quality, delivery is quick. Packaging could be a little more eco-friendly.', ARRAY[]::text[], '1 week ago'),
  ('vr-m3-1', 'store-m3', 'MART'::app_brand, 'seed-aditya-rao', 'Aditya Rao', 5, 'The hoodie fits perfectly and the fabric feels premium. Will order again.', ARRAY[]::text[], '5 days ago'),
  ('vr-m3-2', 'store-m3', 'MART'::app_brand, 'seed-kavya-menon', 'Kavya Menon', 4, 'Trendy collection and genuine products. Sizes run slightly small.', ARRAY[]::text[], '2 weeks ago'),
  ('vr-p1-1', 'store-p1', 'PHARMA'::app_brand, 'seed-dr-sarah-alvi', 'Dr. Sarah Alvi', 5, 'Genuine medicines with clear expiry dates. Reliable for the whole family.', ARRAY[]::text[], '4 days ago'),
  ('vr-p2-1', 'store-p2', 'PHARMA'::app_brand, 'seed-rahul-verma', 'Rahul Verma', 5, 'Well stocked and the pharmacist was helpful with dosage advice.', ARRAY[]::text[], '1 week ago'),
  ('vr-f3-1', 'store-f3', 'FOOD'::app_brand, 'seed-aarav-sharma', 'Aarav Sharma', 5, 'Smash burgers were juicy and the loaded fries arrived hot. Loved it.', ARRAY[]::text[], '3 days ago'),
  ('vr-f3-2', 'store-f3', 'FOOD'::app_brand, 'seed-neha-kapoor', 'Neha Kapoor', 4, 'Tasty food, generous portions. Delivery took a little longer than promised.', ARRAY[]::text[], '1 week ago'),
  ('vr-f8-1', 'store-f8', 'FOOD'::app_brand, 'seed-ravi-desai', 'Ravi Desai', 5, 'Rich, aromatic biryani — the dum flavour really comes through.', ARRAY[]::text[], '2 days ago'),
  ('vr-f7-1', 'store-f7', 'FOOD'::app_brand, 'seed-meera-nair', 'Meera Nair', 5, 'Wood-fired pizza done right. Fresh bufala and a beautifully blistered crust.', ARRAY[]::text[], '6 days ago'),
  ('vr-dn12-1', 'dn-12', 'FOOD'::app_brand, 'seed-priya-patel', 'Priya Patel', 5, 'Best Hyderabadi biryani in the city. The raita and salan were a lovely bonus.', ARRAY[]::text[], '1 week ago');
